function selfThrowOnCooldown(world, actor, target, cooldownTurns) {
  if (!(cooldownTurns > 0)) return false;
  return isAiOnCooldown(world, SELF_THROW_COOLDOWN_KEY, selfThrowCooldownSlot(actor, target));
}

/**
